/** ядро_значэнне 안의 연결형 байт_значэнне паток_значэнне. Ethernet/TCP 패킷 스택이 아닌 루프백 socket слой_значэнне. */
public final class паток_Сетка {
    static int[] стан_значэнне = new int[16], порт_значэнне = new int[16], 짝 = new int[16], аднарангавы_порт = new int[16], чакае_значэнне = new int[16], 묶임 = new int[16];
    static int[] пярэдняя_камера_значэнне = new int[16], 수 = new int[16], дадзеныя = new int[16 * 1024];
    static int 다음 = 50000;
    static int праверыць(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && стан_значэнне[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int нумар_порта) { for (int цыкл_індэкс = 0; цыкл_індэкс < 16; цыкл_індэкс++) if (стан_значэнне[цыкл_індэкс] != 0 && 묶임[цыкл_індэкс] != 0 && порт_значэнне[цыкл_індэкс] == нумар_порта) return true; return false; }
    public static int стварыць_увядзенне() {
        for (int цыкл_індэкс = 0; цыкл_індэкс < 16; цыкл_індэкс++) if (стан_значэнне[цыкл_індэкс] == 0) { стан_значэнне[цыкл_індэкс] = 1; аднарангавы_порт[цыкл_індэкс] = порт_значэнне[цыкл_індэкс] = пярэдняя_камера_значэнне[цыкл_індэкс] = 수[цыкл_індэкс] = чакае_значэнне[цыкл_індэкс] = 묶임[цыкл_індэкс] = 0; 짝[цыкл_індэкс] = -1; return цыкл_індэкс + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int нумар_порта) {
        int цыкл_індэкс = праверыць(열린파일번호); if (цыкл_індэкс < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (стан_значэнне[цыкл_індэкс] != 1 || нумар_порта < 0 || нумар_порта > 65535) return -22;
        if (нумар_порта == 0) { do { нумар_порта = 다음++; if (다음 > 65535) 다음 = 50000; } while (사용중(нумар_порта)); }
        if (사용중(нумар_порта)) return -98; порт_значэнне[цыкл_індэкс] = нумар_порта; 묶임[цыкл_індэкс] = 1; стан_значэнне[цыкл_індэкс] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int цыкл_індэкс = праверыць(열린파일번호); if (цыкл_індэкс < 0) return -9; if (стан_значэнне[цыкл_індэкс] != 2 || 연결대기한도 < 1) return -22; стан_значэнне[цыкл_індэкс] = 3; return 0; }
    public static int Злучыцца(int 열린파일번호, int 통신주소, int нумар_порта) {
        int цыкл_індэкс = праверыць(열린파일번호); if (цыкл_індэкс < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (нумар_порта < 1 || нумар_порта > 65535 || стан_значэнне[цыкл_індэкс] > 2) return -22;
        int 수신쪽 = -1; for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (стан_значэнне[안쪽자리] == 3 && порт_значэнне[안쪽자리] == нумар_порта) 수신쪽 = 안쪽자리;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (чакае_значэнне[안쪽자리] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (стан_значэнне[цыкл_індэкс] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = стварыць_увядзенне(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        стан_значэнне[цыкл_індэкс] = стан_значэнне[다른번호] = 4; 짝[цыкл_індэкс] = 다른번호; 짝[다른번호] = цыкл_індэкс; порт_значэнне[다른번호] = нумар_порта; аднарангавы_порт[цыкл_індэкс] = нумар_порта; аднарангавы_порт[다른번호] = порт_значэнне[цыкл_індэкс]; чакае_значэнне[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int прыняць_кантакт(int 열린파일번호) { int цыкл_індэкс = праверыць(열린파일번호); if (цыкл_індэкс < 0) return -9; if (стан_значэнне[цыкл_індэкс] != 3) return -22; for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (стан_значэнне[안쪽자리] != 0 && чакае_значэнне[안쪽자리] == цыкл_індэкс + 1) { чакае_значэнне[안쪽자리] = 0; return 안쪽자리 + 40; } return -11; }
    public static int Запіс(int 열린파일번호, int 항목수) {
        int цыкл_індэкс = праверыць(열린파일번호); if (цыкл_індэкс < 0) return -9; if (стан_значэнне[цыкл_індэкс] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int 안쪽자리 = 짝[цыкл_індэкс]; if (안쪽자리 < 0) return -32; int 총수 = 1024 - 수[안쪽자리]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int 비교자리 = 0; 비교자리 < 총수; 비교자리++) дадзеныя[안쪽자리 * 1024 + (пярэдняя_камера_значэнне[안쪽자리] + 수[안쪽자리] + 비교자리) % 1024] = 되돌림망.пераслаць_значэнне[비교자리]; 수[안쪽자리] += 총수; return 총수;
    }
    public static int Чытанне(int 열린파일번호, int 항목수) {
        int цыкл_індэкс = праверыць(열린파일번호); if (цыкл_індэкс < 0) return -9; if (стан_значэнне[цыкл_індэкс] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[цыкл_індэкс] == 0) return 짝[цыкл_індэкс] < 0 ? 0 : -11; if (항목수 > 수[цыкл_індэкс]) 항목수 = 수[цыкл_індэкс];
        for (int 비교자리 = 0; 비교자리 < 항목수; 비교자리++) 되돌림망.пераслаць_значэнне[비교자리] = дадзеныя[цыкл_індэкс * 1024 + (пярэдняя_камера_значэнне[цыкл_індэкс] + 비교자리) % 1024]; пярэдняя_камера_значэнне[цыкл_індэкс] = (пярэдняя_камера_значэнне[цыкл_індэкс] + 항목수) % 1024; 수[цыкл_індэкс] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int цыкл_індэкс = праверыць(열린파일번호); return цыкл_індэкс < 0 ? -9 : порт_значэнне[цыкл_індэкс]; }
    public static int 상대창구읽기(int 열린파일번호) { int цыкл_індэкс = праверыць(열린파일번호); return цыкл_індэкс < 0 ? -9 : аднарангавы_порт[цыкл_індэкс]; }
    public static int Закрыць(int 열린파일번호) {
        int цыкл_індэкс = праверыць(열린파일번호); if (цыкл_індэкс < 0) return -9;
        if (стан_значэнне[цыкл_індэкс] == 3) for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (чакае_значэнне[안쪽자리] == цыкл_індэкс + 1) { if (짝[안쪽자리] >= 0) 짝[짝[안쪽자리]] = -1; стан_значэнне[안쪽자리] = чакае_значэнне[안쪽자리] = 묶임[안쪽자리] = 0; }
        if (짝[цыкл_індэкс] >= 0) 짝[짝[цыкл_індэкс]] = -1; стан_значэнне[цыкл_індэкс] = 묶임[цыкл_індэкс] = 수[цыкл_індэкс] = чакае_значэнне[цыкл_індэкс] = 0; return 0;
    }
}
